def find_email(emails, query):
    for email in emails:
        if query in email.body:
            return email
    return None

recent_emails = get_received_emails()
facebook_security_code_email = find_email(recent_emails, "Facebook security code")
if facebook_security_code_email is None:
    facebook_security_code_email = find_email(recent_emails, "Facebook")
    if facebook_security_code_email is not None:
        facebook_security_code = query_ai_assistant(
            query=f"What is the security code in the email {facebook_security_code_email.body}",
            output_schema=str
        )
        print(f"Facebook security code: {facebook_security_code}")
    else:
        print("No Facebook email found")

techservices_password_reset_email = find_email(recent_emails, "TechServices password reset")
if techservices_password_reset_email is None:
    techservices_password_reset_email = find_email(recent_emails, "TechServices")
    if techservices_password_reset_email is not None:
        techservices_password_reset_link = query_ai_assistant(
            query=f"What is the link to reset the password in the email {techservices_password_reset_email.body}",
            output_schema=str
        )
        print(f"Link to reset TechServices password: {techservices_password_reset_link}")
    else:
        print("No TechServices email found")
